/**
 * Natural key to systemId mapping for insert+query pattern.
 *
 * @template TKey - Type of natural key (number for simple entities, string for composite keys)
 */
export interface NaturalIdMapping<TKey = number> {
  /** Natural identifier used in the request */
  naturalId: TKey;
  /** Resolved systemId generated by persistence layer */
  systemId: number;
}

/**
 * Generic insert error with domain-oriented context.
 * DB-agnostic and focused on business logic failures.
 *
 * @template E - Entity type constrained by aggregate-specific unions
 */
export interface InsertError<E extends string = string> {
  /** Parent systemId if root insert succeeded (for correlation) */
  systemId?: number;
  /** Entity type (constrained by aggregate-specific unions) */
  entity: E;
  /** Natural ID of the failing entity */
  naturalId: string;
  /** Domain error code (e.g., VALIDATION_FAILED, DUPLICATE, FK_CONSTRAINT) */
  code: string;
  /** Human-readable message */
  message: string;
  /** Optional original domain object reference for correlation */
  domainObjectRef?: unknown;
  /** Optional cause chain with additional hints */
  causes?: Array<{code: string; message: string}>;
}

/**
 * Simple entity insert result (no child mappings).
 */
export interface EntityInsertResult<TKey = number> {
  idMapping?: NaturalIdMapping<TKey>;
  errors: InsertError[];
  success: boolean;
}

export interface BulkEntityInsertResult<TKey = number> {
  results: EntityInsertResult<TKey>[];
}
